import base64, hashlib, os, pathlib, stat
root=pathlib.Path('/home/qian/hepta-runtime-optimization-20261106-r33')
assert root.resolve(strict=True)==root and root.stat().st_uid==os.getuid()==1000
directory=root/'observation-archive-tools-01'
directory.mkdir(mode=0o700)
raw=base64.b64decode('',validate=True)
assert len(raw)==39336 and hashlib.sha256(raw).hexdigest()=='d9aedf45f00d9e7a525de89d348aca7081be4df480b747b4464d4fdc0fb313ce'
path=directory/'archive_r33_observation.py'
fd=os.open(path,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o600)
with os.fdopen(fd,'wb') as stream:
    stream.write(raw); stream.flush(); os.fsync(stream.fileno())
assert path.read_bytes()==raw
os.execv('/usr/bin/python3',['/usr/bin/python3','-B','-u',str(path),'--kind','observation'])
